  let diff = a2 - a1;
  while(diff <= -Math.PI) diff += 2*Math.PI;
  while(diff > Math.PI) diff -= 2*Math.PI;

  const sweep = diff > 0 ? 1 : 0;
  return `M ${start.x} ${start.y} A ${radius} ${radius} 0 0 ${sweep} ${end.x} ${end.y}`;
}

function render() {
  const isA = currentState.scenarioToggle.includes('(a)');
  const state = currentState.stackUpdate;

  if (isA) {
    groupA.show();
    groupB.hide();

    const qjPts = ptsA.filter(p => p.id !== 'pi').map(p => [p.x, p.y]);
