        if (state === 'idle') {
          dot.stroke({color: '#c0392b', width: 2}).radius(5);
        } else {
          dot.stroke('none').radius(4);
        }
      }
    });
  } else {
    groupA.hide();
    groupB.show();

    if (state === 'idle') {
      triB.hide();
      angleArcB.hide();
      dashedBoundB.hide();
      boundB.plot(ptsB.filter(p => p.id !== 'pi').map(p => [p.x, p.y]));
    } else if (state === 'check_turn') {
      triB.hide();
      boundB.plot(ptsB.filter(p => p.id !== 'pi').map(p => [p.x, p.y]));
      dashedBoundB.show().plot([[mapB.pt.x, mapB.pt.y], [mapB.pi.x, mapB.pi.y]]);
      angleArcB.show().plot(getAngleArc(mapB.pt, mapB.pr, mapB.pi, 25));
    } else if (state === 'update_stack') {
      triB.show().plot([[mapB.p0.x, mapB.p0.y], [mapB.pr.x, mapB.pr.y], [mapB.pi.x, mapB.pi.y]]);
      boundB.plot(ptsB.filter(p => p.id !== 'pt').map(p => [p.x, p.y]));
      dashedBoundB.show().plot([[mapB.pr.x, mapB.pr.y], [mapB.pt.x, mapB.pt.y], [mapB.pi.x, mapB.pi.y]]);
      angleArcB.show().plot(getAngleArc(mapB.pt, mapB.pr, mapB.pi, 25));
    }

    dotsB.children().forEach((dot, idx) => {
      if (ptsB[idx].id === 'pi') {
        const active = (state === 'idle' || state === 'check_turn');
        dot.fill(active ? '#e74c3c' : '#000');
        if (active) {
          dot.stroke({color: '#c0392b', width: 2}).radius(5);
        } else {
          dot.stroke('none').radius(4);
        }
      }
    });
  }
}

